using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "HurricaneNextTurnEffect", menuName = "Data/Battle/Effects/Austra/HurricaneNextTurn Effect")]
public class HurricaneNextTurnEffect : Effect
{
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), playerEffectsList.HurricaneActiveEffect.GetDrawActionDescription());
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		component.AddEffect(playerEffectsList.HurricaneActiveEffect, amount);
		component.RemoveEffect(this, activateFeedback: false);
		return amount;
	}
}
